from django.db import migrations, models


def cancelar_turnos_duplicados(apps, schema_editor):
    """Antes de la restriccion podian quedar dos turnos del mismo
    veterinario a la misma hora. De cada grupo se conserva el primero
    (menor id) y los demas pasan a CANCELADO; no se borra nada."""
    Turno = apps.get_model('atencion', 'Turno')
    vistos = set()
    activos = Turno.objects.exclude(estado='CANCELADO').order_by('id')
    for turno in activos:
        clave = (turno.veterinario_id, turno.fecha_hora)
        if clave in vistos:
            turno.estado = 'CANCELADO'
            turno.save(update_fields=['estado'])
        else:
            vistos.add(clave)


